#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    if (!(cin >> n)) return 0;
    long long ans = 0;
    for (int i = 0; i < n; ++i) {
        int m;
        string s;
        cin >> m;
        cin >> s; // 输入保证只含字母，长度为 m
        // 条件1：首字母必须是大写
        if (s.empty() || !(s[0] >= 'A' && s[0] <= 'Z')) continue;
        // 条件2：尾字母必须是小写
        if (!(s.back() >= 'a' && s.back() <= 'z')) continue;

        int lowerMask = 0, upperMask = 0;
        bool ok = true;
        for (char ch : s) {
            if (ch >= 'a' && ch <= 'z') {
                int idx = ch - 'a';
                if (upperMask & (1 << idx)) { // 同一字母的大写已出现，冲突
                    ok = false; break;
                }
                lowerMask |= (1 << idx);
            } else if (ch >= 'A' && ch <= 'Z') {
                int idx = ch - 'A';
                if (lowerMask & (1 << idx)) { // 同一字母的小写已出现，冲突
                    ok = false; break;
                }
                upperMask |= (1 << idx);
            } else {
                ok = false; break; // 保险：非字母直接不符合（按题意不会发生）
            }
        }
        if (ok) ++ans;
    }
    cout << ans << '\n';
    return 0;
}
